// Determine next action based on current round and remaining disputable items
const inp = $input.first().json;
const caseId = inp.case_id;
const currentRound = inp.current_round || 1;
const remainingDisputable = inp.remaining_disputable || 0;
const maxRounds = 3;

let action, newStatus, newRound;

if (remainingDisputable === 0) {
  // All items resolved
  action = 'resolve';
  newStatus = 'resolved';
  newRound = currentRound;
} else if (currentRound < maxRounds) {
  // Escalate to next round
  action = 'escalate';
  newStatus = 'in_progress';
  newRound = currentRound + 1;
} else {
  // Max rounds reached — recommend legal action
  action = 'recommend_legal';
  newStatus = 'escalating';
  newRound = currentRound;
}

return [{ json: {
  case_id: caseId,
  action,
  new_status: newStatus,
  new_round: newRound,
  remaining_disputable: remainingDisputable,
  notification_type: action === 'resolve' ? 'case_resolved'
    : action === 'escalate' ? 'escalated_round_' + newRound
    : 'legal_action_recommended'
} }];
